/// Native replay implementations for io bindings.
#[inline]
fn destack_io_completion_cancel_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut u32,
    handle: resource::CompletionHandle,
    target: resource::ResourceId,
) -> RuntimeResult<()> {
    let _ = (&handle, &target);

    binding.trace().run_binding_without_context(
        IO_COMPLETION_CANCEL,
        binding.replay_payload_for(IO_COMPLETION_CANCEL)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_io_completion_cancel(binding, out, handle, target)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_io_completion_cancel(
                    binding, out, handle, target,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: u32 = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = IoCompletionCancelReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IoCompletionCancelReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

