#[inline]
fn destack_io_completion_wait_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<CompletionEvent>,
    handle: resource::CompletionHandle,
    timeoutns: u64,
    maxevents: u32,
) -> RuntimeResult<()> {
    let _ = (&handle, &timeoutns, &maxevents);

    binding.trace().run_binding_without_context(
        IO_COMPLETION_WAIT,
        binding.replay_payload_for(IO_COMPLETION_WAIT)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_io_completion_wait(
                    binding, out, handle, timeoutns, maxevents,
                )
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_io_completion_wait(
                    binding, out, handle, timeoutns, maxevents,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeArray<CompletionEvent> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded_key = result_recorded_item.key;
                    let result_recorded_item_recorded_result = result_recorded_item.result;
                    let result_recorded_item_recorded_flags = result_recorded_item.flags;
                    let result_recorded_item_recorded = CompletionEvent {
                        key: result_recorded_item_recorded_key,
                        result: result_recorded_item_recorded_result,
                        flags: result_recorded_item_recorded_flags,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = IoCompletionWaitReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IoCompletionWaitReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native =
                        binding.store_array_with(value.len(), |value_native_values| {
                            for value_native_item in value {
                                let value_native_decoded_key = value_native_item.key;
                                let value_native_decoded_result = value_native_item.result;
                                let value_native_decoded_flags = value_native_item.flags;
                                let value_native_decoded = CompletionEvent {
                                    key: value_native_decoded_key,
                                    result: value_native_decoded_result,
                                    flags: value_native_decoded_flags,
                                };
                                value_native_values.push(value_native_decoded);
                            }
                            Ok(())
                        })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

