/// VM replay implementations for io bindings.
#[inline]
fn destack_io_completion_cancel_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::CompletionHandle,
    target: resource::ResourceId,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        IO_COMPLETION_CANCEL,
        binding.replay_payload_for(IO_COMPLETION_CANCEL)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_io_completion_cancel(binding, context, handle, target)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_io_completion_cancel(
                binding, context, handle, target,
            ),
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: u32 = value.clone();
                let result_recorded = result_value;
                let payload = IoCompletionCancelReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IoCompletionCancelReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_io_completion_cancel_result(context, result)?;
    Ok(result)
}

