#[inline]
fn destack_io_poll_wait_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::PollHandle,
    timeoutns: u64,
    maxevents: u32,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        IO_POLL_WAIT,
        binding.replay_payload_for(IO_POLL_WAIT)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_io_poll_wait(binding, context, handle, timeoutns, maxevents)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_io_poll_wait(
                binding, context, handle, timeoutns, maxevents,
            ),
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmArray<PollEventVm> = value.clone();
                let result_recorded_raw = result_value.values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item =
                        <PollEventVm as VmAggregateCodec>::decode_with_context(
                            context,
                            result_recorded_item_value,
                        )?;
                    let result_recorded_item_recorded_key = result_recorded_item.key;
                    let result_recorded_item_recorded_ready = result_recorded_item.ready;
                    let result_recorded_item_recorded_data = result_recorded_item.data;
                    let result_recorded_item_recorded = PollEvent {
                        key: result_recorded_item_recorded_key,
                        ready: result_recorded_item_recorded_ready,
                        data: result_recorded_item_recorded_data,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = IoPollWaitReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IoPollWaitReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder =
                        VmArray::<PollEventVm>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value_key = vm_result_item.key;
                        let vm_result_item_value_ready = vm_result_item.ready;
                        let vm_result_item_value_data = vm_result_item.data;
                        let vm_result_item_value = PollEvent {
                            key: vm_result_item_value_key,
                            ready: vm_result_item_value_ready,
                            data: vm_result_item_value_data,
                        };
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_io_poll_wait_result(context, result)?;
    Ok(result)
}

