fn destack_io_uring_unregister_files_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::UringHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        IO_URING_UNREGISTER_FILES,
        binding.replay_payload_for(IO_URING_UNREGISTER_FILES)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_io_uring_unregister_files(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_io_uring_unregister_files(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = IoUringUnregisterFilesReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IoUringUnregisterFilesReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_io_uring_unregister_files_result(context, result)?;
    Ok(result)
}

